async (url: string) => {
      if (!hasWindow) return { ok: false, error: 'web_host_open_external_unavailable' };
      try {
        const opened = window.open(url, '_blank');
        if (!opened) return { ok: false, error: 'web_host_open_external_blocked' };
        return undefined;
      } catch {
        return { ok: false, error: 'web_host_open_external_unavailable' };
      }
    }

(callback: (tab?: string) => void) => {
      const listener = (event: Event) => {
        callback((event as CustomEvent<{ tab?: string }>).detail?.tab);
      };
      window.addEventListener(OPEN_SETTINGS_EVENT, listener);
      return () => window.removeEventListener(OPEN_SETTINGS_EVENT, listener);
    }

(value: string) => {
      const url = browserSafeUrl(value);
      if (url) window.open(url, '_blank', 'noopener,noreferrer');
    }
